# Surah At-Tawbah (chapter 9) — part 11: ayat 95-104 (IDs 1330-1339)
SURAH = 9

ENTRIES = {
1330: (
"وہ — تمہارے — سامنے — اللہ کی قسم — کھائیں گے — جب — تم — ان — کے — پاس — لوٹ جاؤ گے — تاکہ — تم — ان — سے — کنارہ کش ہو جاؤ — پس — ان — سے — کنارہ کش ہو جاؤ — بے شک — وہ — ناپاک — ہیں — اور — ان کا ٹھکانہ — جہنم ہے — ان — کے کیے کا بدلہ",
"""۱۔ منافق — لوٹنے پر — قسمیں کھائیں گے — تاکہ — بچ جائیں۔
۲۔ ’’سَيَحْلِفُونَ بِاللَّهِ لَكُمْ إِذَا انقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا عَنْهُمْ فَأَعْرِضُوا عَنْهُمْ إِنَّهُمْ رِجْسٌ وَمَأْوَاهُمْ جَهَنَّمُ جَزَاءً بِمَا كَانُوا يَكْسِبُونَ‘‘ — وہ — تمہارے — سامنے — اللہ کی قسم — کھائیں گے — جب — تم — ان — کے — پاس — لوٹ جاؤ گے — تاکہ — تم — ان — سے — کنارہ کش ہو جاؤ — پس — ان — سے — کنارہ کش ہو جاؤ — بے شک — وہ — ناپاک — ہیں — اور — ان کا ٹھکانہ — جہنم ہے — ان — کے کیے کا بدلہ — یعنی منافق — لوٹنے پر — جھوٹے قسمیں کھاتے ہیں — انہیں — ناپاک سمجھ کر چھوڑ دو؛ ان کا ٹھکانا — جہنم ہے۔
۳۔ عملی سبق: منافق کی قسم پر — بھروسا — مت کرو۔"""
),
1331: (
"وہ — تم — سے — قسمیں کھائیں گے — تاکہ — تم — ان سے — راضی ہو جاؤ — پس — اگر — تم — ان سے راضی بھی ہو جاؤ — تو — اللہ — فاسقوں — سے — راضی نہیں ہوتا",
"""۱۔ منافق — قسموں کے ذریعے — راضی ہونے کی کوشش کرتے ہیں۔
۲۔ ’’يَحْلِفُونَ لَكُمْ لِتَرْضَوْا عَنْهُمْ فَإِن تَرْضَوْا عَنْهُمْ فَإِنَّ اللَّهَ لَا يَرْضَىٰ عَنِ الْقَوْمِ الْفَاسِقِينَ‘‘ — وہ — تم — سے — قسمیں کھائیں گے — تاکہ — تم — ان سے — راضی ہو جاؤ — پس — اگر — تم — ان سے راضی بھی ہو جاؤ — تو — اللہ — فاسقوں — سے — راضی نہیں ہوتا — یعنی منافق — قسمیں کھا کر — راضی کرنے کی — کوشش کرتے ہیں — مگر — اللہ — فاسقوں سے — راضی نہیں ہوتا۔
۳۔ عملی سبق: رضائے الٰہی — سب سے بڑی دولت ہے؛ فاسقی سے بچو۔"""
),
1332: (
"اعرابی — کفر اور نفاق میں — سب سے بڑھ کر ہیں — اور — وہ — اس چیز کے — لائق — ہیں — کہ — اللہ — نے — اپنے رسولؐ — پر — جو — اتارا — اس کی — حدود — نہ — سمجھیں — اور — اللہ — جاننے والا حکمت والا ہے",
"""۱۔ اعرابی — میں — عام طور پر — کفر اور نفاق — زیادہ پایا جاتا ہے۔
۲۔ ’’الْأَعْرَابُ أَشَدُّ كُفْرًا وَنِفَاقًا وَأَجْدَرُ أَلَّا يَعْلَمُوا حُدُودَ مَا أَنزَلَ اللَّهُ عَلَىٰ رَسُولِهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ‘‘ — اعرابی — کفر اور نفاق میں — سب سے بڑھ کر ہیں — اور — وہ — اس چیز کے — لائق — ہیں — کہ — اللہ — نے — اپنے رسولؐ — پر — جو — اتارا — اس کی — حدود — نہ — سمجھیں — اور — اللہ — جاننے والا حکمت والا ہے — یعنی اعرابی — میں — عام طور پر — کفر اور نفاق — زیادہ پایا جاتا ہے — مگر — اللہ — جاننے والا — اور حکمت والا — ہے۔
۳۔ عملی سبق: ماحول — اثر انداز ہوتا ہے؛ اللہ سے ڈرتے رہو۔"""
),
1333: (
"اور — اعرابیوں میں — کوئی — ایسا بھی ہے — جو اپنے — خرچ — کو تاوان سمجھتا ہے — اور — تمہاری گردش — کا انتظار کرتا ہے — ان پر — برائی کی گردش — ہو — اور — اللہ — سننے والا جاننے والا ہے",
"""۱۔ اعرابی — خرچ کو — تاوان سمجھتے ہیں اور — گردش انتظار کرتے ہیں۔
۲۔ ’’وَمِنَ الْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًا وَيَتَرَبَّصُ بِكُمُ الدَّوَائِرَ عَلَيْهِمْ دَائِرَةُ السَّوْءِ وَاللَّهُ سَمِيعٌ عَلِيمٌ‘‘ — اور — اعرابیوں میں — کوئی — ایسا بھی ہے — جو اپنے — خرچ — کو تاوان سمجھتا ہے — اور — تمہاری گردش — کا انتظار کرتا ہے — ان پر — برائی کی گردش — ہو — اور — اللہ — سننے والا جاننے والا ہے — یعنی بعض اعرابی — خرچ کو تاوان سمجھتے ہیں — اور — تمہارے زوال — کی امید رکھتے ہیں — ان پر — برا گردش — ہے۔
۳۔ عملی سبق: نیت — خرچ کا معیار ہے؛ نہ کہ — مقدار۔"""
),
1334: (
"اور — اعرابیوں میں — کوئی — ایسا بھی ہے — جو — اللہ اور قیامت کے دن — پر ایمان لاتا ہے — اور — اپنے خرچ — کو — اللہ کے نزدیک — قربت اور رسولؐ — کی دعائیں — قرار دیتا ہے — سنو — یقیناً یہ — ان کے لیے — قربت ہے — عنقریب — اللہ — انہیں — اپنی رحمت میں داخل کرے گا — بے شک اللہ — بخشنے والا مہربان ہے",
"""۱۔ اعرابی — جو — سچا ایمان رکھتے ہیں اور — خرچ کو — قربت سمجھتے ہیں۔
۲۔ ’’وَمِنَ الْأَعْرَابِ مَن يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَاتٍ عِندَ اللَّهِ وَصَلَوَاتِ الرَّسُولِ أَلَا إِنَّهَا قُرْبَۃٌ لَّهُمْ سَيُدْخِلُهُمُ اللَّهُ فِي رَحْمَتِهِ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ‘‘ — اور — اعرابیوں میں — کوئی — ایسا بھی ہے — جو — اللہ اور قیامت کے دن — پر ایمان لاتا ہے — اور — اپنے خرچ — کو — اللہ کے نزدیک — قربت اور رسولؐ — کی دعائیں — قرار دیتا ہے — سنو — یقیناً یہ — ان کے لیے — قربت ہے — عنقریب — اللہ — انہیں — اپنی رحمت میں داخل کرے گا — بے شک اللہ — بخشنے والا مہربان ہے — یعنی بعض اعرابی — سچا ایمان رکھتے ہیں اور — خرچ کو اللہ کی قربت سمجھتے ہیں؛ اللہ — انہیں — رحمت میں داخل کرے گا۔
۳۔ عملی سبق: سچا ایمان — خرچ کو — قربت — بنا دیتا ہے۔"""
),
1335: (
"اور — سب سے — پہلے — ہجرت کرنے والے — مہاجرین اور انصار — اور — جو — لوگ — ان کی پیروی — احسان کے ساتھ — کرتے ہیں — اللہ — ان سے — راضی ہو گیا — اور — وہ — اس سے — راضی ہو گئے — اور — اس نے — ان کے لیے — ایسی جنتیں — تیار کر رکھی ہیں — جن کے نیچے نہریں بہتی ہیں — وہ — ان میں — ہمیشہ ہمیشہ — رہیں گے — یہی — عظیم کامیابی — ہے",
"""۱۔ سب سے پہلے ہجرت کرنے والے — مہاجرین اور انصار — اللہ کی رضامندی۔
۲۔ ’’وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنصَارِ وَالَّذِينَ اتَّبَعُوهُم بِإِحْسَانٍ رَّضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ وَأَعَدَّ لَهُمْ جَنَّاتٍ تَجْرِي تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَٰلِكَ الْفَوْزُ الْعَظِيمُ‘‘ — اور — سب سے — پہلے — ہجرت کرنے والے — مہاجرین اور انصار — اور — جو — لوگ — ان کی پیروی — احسان کے ساتھ — کرتے ہیں — اللہ — ان سے — راضی ہو گیا — اور — وہ — اس سے — راضی ہو گئے — اور — اس نے — ان کے لیے — ایسی جنتیں — تیار کر رکھی ہیں — جن کے نیچے نہریں بہتی ہیں — وہ — ان میں — ہمیشہ ہمیشہ — رہیں گے — یہی — عظیم کامیابی — ہے — یعنی سب سے پہلے ہجرت کرنے والے — مہاجرین اور انصار — اور ان کے بہترین پیروکار — اللہ — کی رضامندی — پا گئے۔
۳۔ عملی سبق: مہاجرین اور انصار کی — پیروی — احسان کے ساتھ — کامیابی کا راستہ ہے۔"""
),
1336: (
"اور — تمہارے — گرد — رہنے والے — اعرابی — میں سے — کچھ منافق ہیں — اور — اہلِ مدینہ میں سے — بھی — وہ — نفاق میں پختہ ہو گئے — تم — انہیں نہیں جانتے — ہم — انہیں جانتے ہیں — ہم — انہیں دو بار عذاب دیں گے — پھر — وہ — عظیم عذاب — کی طرف — لوٹائے جائیں گے",
"""۱۔ مدینہ کے آس پاس — بھی منافق — موجود ہیں — نفاق میں پختہ۔
۲۔ ’’وَمِمَّنْ حَوْلَكُم مِّنَ الْأَعْرَابِ مُنَافِقُونَ وَمِنْ أَهْلِ الْمَدِينَۃِ مَرَدُوا عَلَى النِّفَاقِ لَا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ‘‘ — اور — تمہارے — گرد — رہنے والے — اعرابی — میں سے — کچھ منافق ہیں — اور — اہلِ مدینہ میں سے — بھی — وہ — نفاق میں پختہ ہو گئے — تم — انہیں نہیں جانتے — ہم — انہیں جانتے ہیں — ہم — انہیں دو بار عذاب دیں گے — پھر — وہ — عظیم عذاب — کی طرف — لوٹائے جائیں گے — یعنی منافق — ہر جگہ موجود ہیں — مگر — اللہ — انہیں جانتا ہے؛ انہیں عذاب ملے گا۔
۳۔ عملی سبق: نفاق — کسی — کو دھوکا نہیں دے سکتا — اللہ کے سامنے — کوئی پردہ نہیں۔"""
),
1337: (
"اور — دوسرے لوگ — جنہوں نے — اپنے گناہوں کا — اعتراف کیا — انہوں نے — نیک عمل — اور — برے عمل — کو — ملا دیا — شاید — اللہ — ان کی توبہ قبول کرے — بے شک — اللہ — بخشنے والا مہربان ہے",
"""۱۔ توبہ — گناہ کا علاج — اللہ قبول کرتا ہے۔
۲۔ ’’وَآخَرُونَ اعْتَرَفُوا بِذُنُوبِهِمْ خَلَطُوا عَمَلًا صَالِحًا وَآخَرَ سَيِّئًا عَسَى اللَّهُ أَن يَتُوبَ عَلَيْهِمْ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ‘‘ — اور — دوسرے لوگ — جنہوں نے — اپنے گناہوں کا — اعتراف کیا — انہوں نے — نیک عمل — اور — برے عمل — کو — ملا دیا — شاید — اللہ — ان کی توبہ قبول کرے — بے شک — اللہ — بخشنے والا مہربان ہے — یعنی کچھ لوگ — اپنے گناہوں کا اعتراف کرتے ہیں؛ اللہ — ان کی توبہ — قبول کر سکتا ہے۔
۳۔ عملی سبق: توبہ — اللہ کے نزدیک — پسندیدہ ہے؛ اپنے گناہوں کا اعتراف کرو۔"""
),
1338: (
"تم — ان — کے مالوں میں سے — صدقہ — لو — جس — سے — تم — انہیں پاک اور — سلامت کر دو — اور — ان کے لیے — دعا کرو؛ بے شک تمہاری دعا — ان کے لیے — سکون ہے — اور — اللہ — سننے والا جاننے والا ہے",
"""۱۔ صدقہ — مال کو پاک کرتا ہے اور — دعا سکون دیتی ہے۔
۲۔ ’’خُذْ مِنْ أَمْوَالِهِمْ صَدَقَۃً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ إِنَّ صَلَاتَكَ سَكَنٌ لَّهُمْ وَاللَّهُ سَمِيعٌ عَلِيمٌ‘‘ — تم — ان — کے مالوں میں سے — صدقہ — لو — جس — سے — تم — انہیں پاک اور — سلامت کر دو — اور — ان کے لیے — دعا کرو؛ بے شک تمہاری دعا — ان کے لیے — سکون ہے — اور — اللہ — سننے والا جاننے والا ہے — یعنی رسولؐ — مسلمانوں سے صدقہ لیتے — تاکہ — ان کا مال — پاک ہو اور — ان کے لیے دعا — سکون کا باعث ہے۔
۳۔ عملی سبق: زکوٰۃ اور صدقہ — مال کو — پاک — اور دل کو — مطمئن — کرتے ہیں۔"""
),
1339: (
"کیا — وہ — نہیں جانتے — کہ — اللہ — ہی — اپنے بندوں سے — توبہ قبول کرتا ہے — اور — صدقات — لیتا ہے — اور — یہ — کہ — اللہ — ہی توبہ قبول کرنے والا مہربان ہے",
"""۱۔ اللہ — توبہ قبول کرنے والا — اور — صدقات — لینے والا — ہے۔
۲۔ ’’أَلَمْ يَعْلَمُوا أَنَّ اللَّهَ هُوَ يَقْبَلُ التَّوْبَۃَ عَنْ عِبَادِهِ وَيَأْخُذُ الصَّدَقَاتِ وَأَنَّ اللَّهَ هُوَ التَّوَّابُ الرَّحِيمُ‘‘ — کیا — وہ — نہیں جانتے — کہ — اللہ — ہی — اپنے بندوں سے — توبہ قبول کرتا ہے — اور — صدقات — لیتا ہے — اور — یہ — کہ — اللہ — ہی توبہ قبول کرنے والا مہربان ہے — یعنی اللہ — توبہ قبول کرتا ہے — اور — صدقات کا — بدلہ دیتا ہے؛ وہ — غفور رحیم ہے۔
۳۔ عملی سبق: توبہ کرو — اللہ — قبول کرتا ہے۔"""
),
}
